-- READ ONLY Phase 4 preflight: full semantic dependency, target, lifecycle-width, and RBAC classification.
SET @dependency_tables := (SELECT COUNT(*)=7 FROM information_schema.tables WHERE table_schema='alrowad_uni_rust' AND table_type='BASE TABLE' AND engine='InnoDB' AND table_name IN ('supplementary_exam_periods','supplementary_exam_period_events','supplementary_exam_offerings','supplementary_exam_offering_sources','supplementary_exam_offering_events','supplementary_exam_theoretical_deferrals','supplementary_exam_theoretical_deferral_events'));
SET @dependency_columns := (SELECT COUNT(*)=66 FROM information_schema.columns WHERE table_schema='alrowad_uni_rust' AND ((table_name='supplementary_exam_periods' AND column_name IN ('supplementary_exam_period_id','academic_year_id','semester_id','period_name','start_date','end_date','is_active','status','opened_by_user_id','opened_at','decision_note','created_at','updated_at')) OR (table_name='supplementary_exam_period_events' AND column_name IN ('supplementary_exam_period_event_id','supplementary_exam_period_id','event_type','from_status','to_status','actor_user_id','notes','created_at')) OR (table_name='supplementary_exam_offerings' AND column_name IN ('supplementary_exam_offering_id','supplementary_exam_period_id','academic_program_id','course_id','status','opened_by_user_id','opened_at','closed_by_user_id','closed_at','created_at','updated_at')) OR (table_name='supplementary_exam_offering_sources' AND column_name IN ('supplementary_exam_offering_source_id','supplementary_exam_offering_id','course_offering_id','created_at')) OR (table_name='supplementary_exam_offering_events' AND column_name IN ('supplementary_exam_offering_event_id','supplementary_exam_offering_id','event_type','from_status','to_status','actor_user_id','notes','created_at')) OR (table_name='supplementary_exam_theoretical_deferrals' AND column_name IN ('supplementary_exam_theoretical_deferral_id','supplementary_exam_offering_id','student_course_registration_id','status','current_slot','declared_by_user_id','declared_at','cancelled_by_user_id','cancelled_at','cancellation_reason','superseded_at','supersede_reason','created_at','updated_at')) OR (table_name='supplementary_exam_theoretical_deferral_events' AND column_name IN ('supplementary_exam_theoretical_deferral_event_id','supplementary_exam_theoretical_deferral_id','event_type','from_status','to_status','actor_user_id','notes','created_at'))));
SET @dependency_primary_ai := (SELECT COUNT(*)=7 FROM information_schema.columns c JOIN information_schema.statistics s ON s.table_schema=c.table_schema AND s.table_name=c.table_name AND s.column_name=c.column_name AND s.index_name='PRIMARY' AND s.seq_in_index=1 WHERE c.table_schema='alrowad_uni_rust' AND c.table_name IN ('supplementary_exam_periods','supplementary_exam_period_events','supplementary_exam_offerings','supplementary_exam_offering_sources','supplementary_exam_offering_events','supplementary_exam_theoretical_deferrals','supplementary_exam_theoretical_deferral_events') AND c.column_name=CONCAT(LEFT(c.table_name,LENGTH(c.table_name)-1),'_id') AND c.data_type='int' AND c.column_type NOT LIKE '%unsigned%' AND c.is_nullable='NO' AND c.extra LIKE '%auto_increment%');
SET @dependency_types := (SELECT COUNT(*)=26 FROM information_schema.columns WHERE table_schema='alrowad_uni_rust' AND ((column_name IN ('supplementary_exam_period_id','supplementary_exam_offering_id','student_course_registration_id','declared_by_user_id','actor_user_id') AND data_type='int' AND column_type NOT LIKE '%unsigned%' AND is_nullable='NO') OR (table_name='supplementary_exam_theoretical_deferrals' AND column_name='cancelled_by_user_id' AND data_type='int' AND column_type NOT LIKE '%unsigned%' AND is_nullable='YES') OR (table_name='supplementary_exam_theoretical_deferrals' AND column_name='current_slot' AND data_type='tinyint' AND is_nullable='YES') OR (column_name IN ('status','event_type','to_status') AND data_type='varchar' AND is_nullable='NO') OR (column_name='from_status' AND data_type='varchar' AND is_nullable='YES')));
SET @period_lifecycle_width_ready := (SELECT COUNT(*)=4 FROM information_schema.columns WHERE table_schema='alrowad_uni_rust' AND ((table_name='supplementary_exam_periods' AND column_name='status' AND data_type='varchar' AND character_maximum_length>=19 AND is_nullable='NO') OR (table_name='supplementary_exam_period_events' AND column_name IN ('event_type','to_status') AND data_type='varchar' AND character_maximum_length>=19 AND is_nullable='NO') OR (table_name='supplementary_exam_period_events' AND column_name='from_status' AND data_type='varchar' AND character_maximum_length>=19 AND is_nullable='YES')));
SET @dependency_semantic_uniques := (SELECT COUNT(*)=5 FROM (SELECT table_name,non_unique,GROUP_CONCAT(column_name ORDER BY seq_in_index) cols FROM information_schema.statistics WHERE table_schema='alrowad_uni_rust' AND table_name IN ('supplementary_exam_periods','supplementary_exam_offerings','supplementary_exam_offering_sources','supplementary_exam_theoretical_deferrals') GROUP BY table_name,index_name,non_unique) x WHERE non_unique=0 AND ((table_name='supplementary_exam_periods' AND cols='academic_year_id,semester_id') OR (table_name='supplementary_exam_offerings' AND cols='supplementary_exam_period_id,academic_program_id,course_id') OR (table_name='supplementary_exam_offering_sources' AND cols='supplementary_exam_offering_id,course_offering_id') OR (table_name='supplementary_exam_theoretical_deferrals' AND cols IN ('supplementary_exam_offering_id,student_course_registration_id','student_course_registration_id,current_slot'))));
SET @dependency_fks := (SELECT COUNT(*)=20 FROM information_schema.key_column_usage WHERE table_schema='alrowad_uni_rust' AND referenced_table_schema='alrowad_uni_rust' AND ((table_name='supplementary_exam_periods' AND ((column_name='academic_year_id' AND referenced_table_name='academic_years' AND referenced_column_name='academic_year_id') OR (column_name='semester_id' AND referenced_table_name='semesters' AND referenced_column_name='semester_id') OR (column_name='opened_by_user_id' AND referenced_table_name='users' AND referenced_column_name='user_id'))) OR (table_name='supplementary_exam_period_events' AND ((column_name='supplementary_exam_period_id' AND referenced_table_name='supplementary_exam_periods') OR (column_name='actor_user_id' AND referenced_table_name='users'))) OR (table_name='supplementary_exam_offerings' AND column_name IN ('supplementary_exam_period_id','academic_program_id','course_id','opened_by_user_id','closed_by_user_id')) OR (table_name='supplementary_exam_offering_sources' AND column_name IN ('supplementary_exam_offering_id','course_offering_id')) OR (table_name='supplementary_exam_offering_events' AND column_name IN ('supplementary_exam_offering_id','actor_user_id')) OR (table_name='supplementary_exam_theoretical_deferrals' AND column_name IN ('supplementary_exam_offering_id','student_course_registration_id','declared_by_user_id','cancelled_by_user_id')) OR (table_name='supplementary_exam_theoretical_deferral_events' AND column_name IN ('supplementary_exam_theoretical_deferral_id','actor_user_id'))));
SET @dependency_supporting_indexes := (SELECT COUNT(*)=10 FROM (SELECT table_name,GROUP_CONCAT(column_name ORDER BY seq_in_index) cols FROM information_schema.statistics WHERE table_schema='alrowad_uni_rust' AND table_name IN ('supplementary_exam_period_events','supplementary_exam_offering_events','supplementary_exam_theoretical_deferrals','supplementary_exam_theoretical_deferral_events') GROUP BY table_name,index_name) x WHERE cols IN ('supplementary_exam_period_id','supplementary_exam_period_id,created_at','actor_user_id','event_type,to_status','supplementary_exam_offering_id','supplementary_exam_offering_id,created_at','declared_by_user_id','cancelled_by_user_id','supplementary_exam_theoretical_deferral_id,created_at'));
SET @dependency_rbac := (SELECT COUNT(DISTINCT CONCAT(r.role_code,':',p.permission_code))=10 FROM `alrowad_uni_rust`.`role_permissions` rp JOIN `alrowad_uni_rust`.`roles` r ON r.role_id=rp.role_id AND r.is_active=1 JOIN `alrowad_uni_rust`.`permissions` p ON p.permission_id=rp.permission_id AND p.is_active=1 JOIN `alrowad_uni_rust`.`system_modules` m ON m.module_id=p.module_id AND m.module_code='exams' AND m.is_active=1 WHERE (p.permission_code='supplementary_exams.periods.view' AND r.role_code IN ('dean','vice_president_scientific')) OR (p.permission_code='supplementary_exams.periods.decide' AND r.role_code='vice_president_scientific') OR (p.permission_code IN ('supplementary_exams.offerings.view','supplementary_exams.offerings.manage') AND r.role_code='dean') OR (p.permission_code='supplementary_exams.eligibility.view' AND r.role_code IN ('dean','registration_officer','exam_officer','vice_president_scientific')) OR (p.permission_code='supplementary_exams.deferrals.self' AND r.role_code='student'));
SET @dependency_forbidden_mappings := (SELECT COUNT(*) FROM `alrowad_uni_rust`.`role_permissions` rp JOIN `alrowad_uni_rust`.`roles` r ON r.role_id=rp.role_id JOIN `alrowad_uni_rust`.`permissions` p ON p.permission_id=rp.permission_id WHERE (p.permission_code='supplementary_exams.periods.decide' AND r.role_code<>'vice_president_scientific') OR (p.permission_code='supplementary_exams.offerings.manage' AND r.role_code<>'dean') OR (p.permission_code='supplementary_exams.deferrals.self' AND r.role_code<>'student'));
SET @phase3_ready := @dependency_tables AND @dependency_columns AND @dependency_primary_ai AND @dependency_types AND @dependency_semantic_uniques AND @dependency_fks AND @dependency_supporting_indexes AND @dependency_rbac AND @dependency_forbidden_mappings=0;
SET @reg_exists := (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema='alrowad_uni_rust' AND table_name='supplementary_exam_registrations');
SET @reg_columns := (SELECT COUNT(*)=16 FROM information_schema.columns WHERE table_schema='alrowad_uni_rust' AND table_name='supplementary_exam_registrations' AND ((column_name='supplementary_exam_registration_id' AND data_type='int' AND column_type NOT LIKE '%unsigned%' AND is_nullable='NO' AND extra LIKE '%auto_increment%') OR (column_name IN ('supplementary_exam_offering_id','student_id','student_course_registration_id','registered_by_user_id') AND data_type='int' AND column_type NOT LIKE '%unsigned%' AND is_nullable='NO') OR (column_name='cancelled_by_user_id' AND data_type='int' AND column_type NOT LIKE '%unsigned%' AND is_nullable='YES') OR (column_name='status' AND data_type='varchar' AND character_maximum_length=16 AND is_nullable='NO') OR (column_name='current_slot' AND data_type='tinyint' AND is_nullable='YES') OR (column_name='eligibility_reason' AND data_type='varchar' AND character_maximum_length=40 AND is_nullable='NO') OR (column_name='registration_channel' AND data_type='varchar' AND character_maximum_length=24 AND is_nullable='NO') OR (column_name IN ('registered_at','eligibility_checked_at','created_at','updated_at') AND data_type IN ('datetime','timestamp') AND is_nullable='NO') OR (column_name='cancelled_at' AND data_type IN ('datetime','timestamp') AND is_nullable='YES') OR (column_name='cancellation_reason' AND data_type='text' AND is_nullable='YES')));
SET @reg_engine := (SELECT COUNT(*)=1 FROM information_schema.tables WHERE table_schema='alrowad_uni_rust' AND table_name='supplementary_exam_registrations' AND table_type='BASE TABLE' AND engine='InnoDB');
SET @reg_indexes := (SELECT COUNT(*)=7 FROM (SELECT non_unique,index_name,GROUP_CONCAT(column_name ORDER BY seq_in_index) cols FROM information_schema.statistics WHERE table_schema='alrowad_uni_rust' AND table_name='supplementary_exam_registrations' GROUP BY index_name,non_unique) x WHERE (index_name='PRIMARY' AND cols='supplementary_exam_registration_id') OR (non_unique=0 AND cols IN ('supplementary_exam_offering_id,student_course_registration_id','supplementary_exam_offering_id,student_id,current_slot')) OR cols IN ('student_id,current_slot','supplementary_exam_offering_id,status','registered_by_user_id','cancelled_by_user_id'));
SET @reg_fks := (SELECT COUNT(*)=5 FROM information_schema.key_column_usage WHERE table_schema='alrowad_uni_rust' AND table_name='supplementary_exam_registrations' AND referenced_table_schema='alrowad_uni_rust' AND ((column_name='supplementary_exam_offering_id' AND referenced_table_name='supplementary_exam_offerings' AND referenced_column_name='supplementary_exam_offering_id') OR (column_name='student_id' AND referenced_table_name='students' AND referenced_column_name='student_id') OR (column_name='student_course_registration_id' AND referenced_table_name='student_course_registrations' AND referenced_column_name='student_course_registration_id') OR (column_name IN ('registered_by_user_id','cancelled_by_user_id') AND referenced_table_name='users' AND referenced_column_name='user_id')));
SET @reg_signedness := (SELECT COUNT(*)=5 FROM information_schema.key_column_usage k JOIN information_schema.columns c ON c.table_schema=k.table_schema AND c.table_name=k.table_name AND c.column_name=k.column_name JOIN information_schema.columns p ON p.table_schema=k.referenced_table_schema AND p.table_name=k.referenced_table_name AND p.column_name=k.referenced_column_name WHERE k.table_schema='alrowad_uni_rust' AND k.table_name='supplementary_exam_registrations' AND c.column_type=p.column_type);
SET @reg_state := IF(@reg_exists=0,'ABSENT',IF(@reg_engine AND @reg_columns AND @reg_indexes AND @reg_fks AND @reg_signedness,'COMPATIBLE','CONFLICT'));
SET @event_exists := (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema='alrowad_uni_rust' AND table_name='supplementary_exam_registration_events');
SET @event_columns := (SELECT COUNT(*)=8 FROM information_schema.columns WHERE table_schema='alrowad_uni_rust' AND table_name='supplementary_exam_registration_events' AND ((column_name='supplementary_exam_registration_event_id' AND data_type='int' AND column_type NOT LIKE '%unsigned%' AND is_nullable='NO' AND extra LIKE '%auto_increment%') OR (column_name IN ('supplementary_exam_registration_id','actor_user_id') AND data_type='int' AND column_type NOT LIKE '%unsigned%' AND is_nullable='NO') OR (column_name='event_type' AND data_type='varchar' AND character_maximum_length=24 AND is_nullable='NO') OR (column_name='from_status' AND data_type='varchar' AND character_maximum_length=16 AND is_nullable='YES') OR (column_name='to_status' AND data_type='varchar' AND character_maximum_length=16 AND is_nullable='NO') OR (column_name='notes' AND data_type='text' AND is_nullable='YES') OR (column_name='created_at' AND data_type IN ('datetime','timestamp') AND is_nullable='NO')));
SET @event_engine := (SELECT COUNT(*)=1 FROM information_schema.tables WHERE table_schema='alrowad_uni_rust' AND table_name='supplementary_exam_registration_events' AND table_type='BASE TABLE' AND engine='InnoDB');
SET @event_indexes := (SELECT COUNT(*)=3 FROM (SELECT index_name,GROUP_CONCAT(column_name ORDER BY seq_in_index) cols FROM information_schema.statistics WHERE table_schema='alrowad_uni_rust' AND table_name='supplementary_exam_registration_events' GROUP BY index_name) x WHERE (index_name='PRIMARY' AND cols='supplementary_exam_registration_event_id') OR cols IN ('supplementary_exam_registration_id,created_at','actor_user_id'));
SET @event_fks := (SELECT COUNT(*)=2 FROM information_schema.key_column_usage WHERE table_schema='alrowad_uni_rust' AND table_name='supplementary_exam_registration_events' AND referenced_table_schema='alrowad_uni_rust' AND ((column_name='supplementary_exam_registration_id' AND referenced_table_name='supplementary_exam_registrations' AND referenced_column_name='supplementary_exam_registration_id') OR (column_name='actor_user_id' AND referenced_table_name='users' AND referenced_column_name='user_id')));
SET @event_signedness := (SELECT COUNT(*)=2 FROM information_schema.key_column_usage k JOIN information_schema.columns c ON c.table_schema=k.table_schema AND c.table_name=k.table_name AND c.column_name=k.column_name JOIN information_schema.columns p ON p.table_schema=k.referenced_table_schema AND p.table_name=k.referenced_table_name AND p.column_name=k.referenced_column_name WHERE k.table_schema='alrowad_uni_rust' AND k.table_name='supplementary_exam_registration_events' AND c.column_type=p.column_type);
SET @event_state := IF(@event_exists=0,'ABSENT',IF(@event_engine AND @event_columns AND @event_indexes AND @event_fks AND @event_signedness,'COMPATIBLE','CONFLICT'));
SET @permission_collision := (SELECT COUNT(*) FROM `alrowad_uni_rust`.`permissions` p LEFT JOIN `alrowad_uni_rust`.`system_modules` m ON m.module_id=p.module_id WHERE p.permission_code IN ('supplementary_exams.registrations.view','supplementary_exams.registrations.self','supplementary_exams.registrations.manage','supplementary_exams.registrations.window') AND (p.is_active<>1 OR m.module_code<>'exams' OR m.is_active<>1));
SET @permission_duplicates := (SELECT COUNT(*) FROM (SELECT permission_code FROM `alrowad_uni_rust`.`permissions` WHERE permission_code IN ('supplementary_exams.registrations.view','supplementary_exams.registrations.self','supplementary_exams.registrations.manage','supplementary_exams.registrations.window') GROUP BY permission_code HAVING COUNT(*)>1) d);
SET @off_matrix := (SELECT COUNT(*) FROM `alrowad_uni_rust`.`role_permissions` rp JOIN `alrowad_uni_rust`.`roles` r ON r.role_id=rp.role_id JOIN `alrowad_uni_rust`.`permissions` p ON p.permission_id=rp.permission_id WHERE (p.permission_code='supplementary_exams.registrations.self' AND r.role_code<>'student') OR (p.permission_code IN ('supplementary_exams.registrations.manage','supplementary_exams.registrations.window') AND r.role_code<>'registration_officer') OR (p.permission_code='supplementary_exams.registrations.view' AND r.role_code NOT IN ('registration_officer','exam_officer','dean','vice_president_scientific')));
SET @rbac_safe := @permission_collision=0 AND @permission_duplicates=0 AND @off_matrix=0 AND (SELECT COUNT(*)=5 FROM `alrowad_uni_rust`.`roles` WHERE role_code IN ('student','registration_officer','exam_officer','dean','vice_president_scientific') AND is_active=1) AND (SELECT COUNT(*)=1 FROM `alrowad_uni_rust`.`system_modules` WHERE module_code='exams' AND is_active=1);
SET @target_schema_safe := @reg_state<>'CONFLICT' AND @event_state<>'CONFLICT';
SET @overall := IF(@phase3_ready AND @period_lifecycle_width_ready AND @target_schema_safe AND @rbac_safe,'READY','BLOCKED');
SET @blocker_code := IF(NOT @phase3_ready,'PHASE3_NOT_DEPLOYED',IF(NOT @period_lifecycle_width_ready,'PERIOD_LIFECYCLE_SCHEMA_TOO_NARROW',IF(NOT @target_schema_safe,'TARGET_SCHEMA_CONFLICT',IF(NOT @rbac_safe,'RBAC_CONFLICT',NULL))));
SELECT 'OVERALL' AS report_section,@overall AS result,@blocker_code AS blocker_code,@phase3_ready AS phase3_ready,@period_lifecycle_width_ready AS period_lifecycle_width_ready,@reg_state AS registrations_state,@event_state AS events_state,@target_schema_safe AS target_schema_safe,@rbac_safe AS rbac_safe;
